#include <iostream>
#include <vector>
#include <string>

int main() {
    int tam;
    std::cin >> tam;
    std::cin.ignore(); // To consume the newline after the integer input
    std::string cad;
    std::getline(std::cin, cad);

    std::vector<std::string> arr;
    int mayor = 0;
    int cont = 0;
    bool flg = false;
    std::string word = "";

    for (int i = 0; i < tam; i++) {
        char ch = cad[i];

        if (ch == '(') {
            if (cont >= mayor) {
                mayor = cont;
            }
            cont = 0;
            flg = true;
            continue;
        }

        if (ch == ')') {
            flg = false;
            if (!word.empty()) {
                arr.push_back(word);
                word.clear();
            }
            continue;
        }

        if (flg && ch != '_') {
            word += ch;
            continue;
        }

        if (flg && ch == '_' && !word.empty()) {
            arr.push_back(word);
            word.clear();
            continue;
        }

        if (!flg && ch != '_') {
            cont++;
            if (i == tam - 1 && cont >= mayor) {
                mayor = cont;
            }
            continue;
        }

        if (!flg && ch == '_') {
            if (cont >= mayor) {
                mayor = cont;
            }
            cont = 0;
        }
    }

    std::cout << mayor << " " << arr.size() << std::endl;

    return 0;
}
